import BottomActionSheet from '../../../../../components/BottomActionSheet'
import {
  Box,
  Box1,
  ButtonPadding,
  DesText,
  Image,
  ShareQuotationDiv,
  ShareQuotationStyle,
  Text,
  Text1,
  Top,
} from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { Button } from '../../../../../components'
import { useCallback, useEffect, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'
import { useGetTravelDetails, useShareCustomerTravelQuote } from '../../state/hooks/useTravelState'
import { useHistory, useParams } from 'react-router'
import { NEW_COPY_ICON, NEW_HOME_ICON, NEW_POLICY_ICON, NEW_SENT_ICON } from '../../../../../images'
import { copySharingData } from '../../../../../helpers/utility'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { APP_HOST } from '../../../../../configs/url'
import { regex } from '../../../../../constants/regex'
import { useErrorContextValue } from '@pasarpolis/common-react-hooks'
import DynamicFormV3 from '../../../../../components/DynamicFormV3'

export const getShareQuotationWithCustomerTravel = () => ({
  fieldData: [
    {
      label: 'Nomor Ponsel',
      type: 'input',
      name: 'mobile_no',
      required: true,
      validator: (value = '') => {
        if (!['+62', '62', '08'].some((pre) => value.startsWith(pre)))
          return ERROR_LANG.phoneNumberNotStartsWith62
        if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
        if (value.length > 14) return ERROR_LANG.max14DigitAllowed
        if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
      },
    },
    {
      label: 'Email',
      type: 'input',
      name: 'email',
      required: true,
      validator: (value = '') => {
        if (!regex.emailRegex.test(value)) {
          return ERROR_LANG.emailRequiredError
        }
        return ''
      },
    },
  ],
})

const validateFormData = (formValues, formFields) => {
  let _error = false
  formFields?.fieldData?.forEach((f) => {
    if (!f.validator) return
    const fieldError = f.validator(formValues[f.name])
    if (fieldError) _error = fieldError
  })
  return _error
}

function ShareQuotation({ show, onClose, loader }) {
  const formRef = useRef()
  const { id } = useParams()
  const history = useHistory()
  const [userBlurred, setUserBlurred] = useState(true)
  const [formValues, setFormValues] = useState({ email: '', mobile_no: '' })
  const [showShareDetailPopup, setShowShareDetailPopup] = useState(false)
  const [{ getTravelDetailsData = {} }, getTravelDetailsRequest] = useGetTravelDetails()
  const [{ shareDraftQuoteData = {} }, sendCustomerQuoteDraft] = useShareCustomerTravelQuote()
  const [{ shareDraftQuoteStatus }, dispatchError] = useErrorContextValue()

  const renderIconText = useCallback((icon, text) => {
    return (
      <Top paddingTop={'20px'}>
        <Image src={icon} alt={text} />
        <Text bold={700} size="10px">
          {text}
        </Text>
      </Top>
    )
  }, [])

  const renderSentIcon = useCallback((icon, text) => {
    return (
      <Top paddingTop={'10px'}>
        <Image src={icon} alt={text} />
      </Top>
    )
  }, [])

  useEffect(() => {
    if (id) {
      // debugger
      getTravelDetailsRequest({ draftQuoteId: id })
    }
  }, [getTravelDetailsRequest, id])

  useEffect(() => {
    if (shareDraftQuoteData.id) {
      setShowShareDetailPopup(true)
    }
  }, [shareDraftQuoteData])

  const body = {
    customer_data: {
      email: formValues.email,
      mobile_no: formValues.mobile_no,
      ...getTravelDetailsData?.customer_detail,
    },
    draft_id: id,
  }

  const handleCustomerForm = (name, value) => {
    setFormValues({
      ...formValues,
      [name]: value,
    })
  }

  const handleSendQuote = () => {
    const hasError = validateFormData(formValues, getShareQuotationWithCustomerTravel())
    if (formValues && !hasError) {
      setShowShareDetailPopup(true)
      sendCustomerQuoteDraft({
        body,
      })
    }
  }

  const getSharingData = (source) => {
    const linkOfShare = `${window.location.hostname}/travel/draft/policy/${id}/?source=${source}`
    return {
      link: linkOfShare,
    }
  }

  const handleCopyLink = () => {
    const sharingDate = getSharingData('quotation_copy')
    copySharingData(sharingDate.link)
    ShowSnackbar.success({
      visible: true,
      text: 'Menyalin ke clipboard berhasil',
    })
  }

  const handleNewPolicy = () => {
    history.push({
      pathname: `/travel`,
    })
  }

  const handleBackHome = () => {
    history.push({
      pathname: `/dashboard`,
    })
  }

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title={'Bagikan Penawaran'}
      zIndex={4}
      showHeader
      backGroundColor
    >
      {!showShareDetailPopup && (
        <>
          <ShareQuotationStyle>
            <CircularLoader isLoading={loader}>
              <DynamicFormV3
                formData={getShareQuotationWithCustomerTravel()}
                onChange={handleCustomerForm}
                ref={formRef}
                values={formValues}
                setUserBlurred={setUserBlurred}
              />
            </CircularLoader>
          </ShareQuotationStyle>
          <ButtonPadding>
            <Button onClick={handleSendQuote} textColor={'black'}>
              {LANG_STRINGS.share}
            </Button>
          </ButtonPadding>
        </>
      )}
      {showShareDetailPopup && (
        <>
          <ShareQuotationDiv>
            <Box1>
              <div className="box-adjust box-content">{renderSentIcon(NEW_SENT_ICON)}</div>
            </Box1>
            <Text1>Tautan Terkirim</Text1>
            <DesText>
              Tautan penawaran asuransi telah berhasil terkirim ke nomor Whatsapp dan Email
              terdaftar.
            </DesText>
            <Text bold={800} size="12px" lineHeight="12px">
              Pilihan Lainnya
            </Text>
            <Box>
              <div onClick={handleCopyLink} className="box-adjust box-content">
                {renderIconText(NEW_COPY_ICON, 'SALIN TAUTAN PENAWARAN')}
              </div>
              <div onClick={handleNewPolicy} className="box-adjust box-content">
                {renderIconText(NEW_POLICY_ICON, 'BUAT PROTEKSI BARU')}
              </div>
              <div onClick={handleBackHome} className="box-adjust box-content">
                {renderIconText(NEW_HOME_ICON, 'KEMBALI KE BERANDA')}
              </div>
            </Box>
          </ShareQuotationDiv>
          <ButtonPadding>
            <Button textColor={'black'} onClick={onClose}>
              TUTUP
            </Button>
          </ButtonPadding>
        </>
      )}
    </BottomActionSheet>
  )
}

export default ShareQuotation
