import { useState, useCallback } from 'react'
import CustomText from '../../../CustomText'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../lang'
import { formatMoney } from '../../../../helpers/utility'
import { regex } from '../../../../constants/regex'
import RadioV2 from '../../../RadioV2'
import {
  PaymentBreakupWrraper,
  PaymentHeader,
  PaymentTotalText,
  Hr,
  DiscountWrraper,
  DiscountHeader,
  TotalTransaction,
  PaymentDetailCtn,
  DiscountInputWrapper
} from './index.style'

const PaymentBreakUp = ({ paymentMap, maxDiscountPercent = 0, maxDiscount, onDiscountChange = () => {}, totalBill = 0, setDisableBtn = () => {}, handleBuy = () => {}, isRedirected = false, showDiscountCtn = true, showDiscountAmount = false }) => {
  const [showAddDiscount, setShowAddDiscount] = useState(!!paymentMap.discount_amount)
  const [discountType, setDiscountType] = useState('nominal')
  const [discountError, setDiscountError] = useState(false)
  const [discountValue, setDiscountValue] = useState(paymentMap.discount_amount)
  const [discountPercent, setDiscountPercent] = useState(0)

  const handleShowAddDiscount = useCallback(() => {
    setShowAddDiscount(prevValue => !prevValue)
    if (showAddDiscount) {
      setDiscountValue(0)
      setDiscountPercent(0)
      onDiscountChange(0)
    }
  }, [showAddDiscount, onDiscountChange])

  const handleDiscountType = useCallback((type) => {
    // handle the discount
    setDiscountType(type)
    setDiscountError(false)
    setDiscountValue(0)
    setDiscountPercent(0)
    onDiscountChange(0)
    handleBuy(0)
  }, [])

  const getDiscountAmount = useCallback((value = 0) => {
    if (discountType === 'nominal') {
      return Number(value) || 0
    } else {
      return Math.floor(paymentMap.sub_total * (value / 100))
    }
  }, [discountType, paymentMap])

  const handlePercentageValue = useCallback((e) => {
    const isPercentageType = discountType === 'percentage'
    const value = e.target.value
    const finalDiscount = getDiscountAmount(value)
    if (value < 0 || !regex.numberDecimal.test(value)) return
    if ((value > maxDiscount) || (isPercentageType && (value > maxDiscountPercent))) {
      setDiscountError(true)
      setDisableBtn(true)
      setDiscountValue(finalDiscount)
      setDiscountPercent(value)
      onDiscountChange && onDiscountChange(finalDiscount)
      return false
    }
    setDiscountValue(finalDiscount)
    setDiscountPercent(value)
    onDiscountChange && onDiscountChange(finalDiscount)
    setDiscountError(false)
    setDisableBtn(false)
  }, [
    discountType, getDiscountAmount, maxDiscountPercent,
    maxDiscount, onDiscountChange
  ])

  const renderDiscountAddContainer = (discountType) => {
    return (
      <DiscountInputWrapper>
        <RadioV2
          data={[
            {
              value: 'nominal',
              name: LANG_STRINGS.nominalNew
            },
            {
              value: 'percentage',
              name: LANG_STRINGS.percentageNew
            }
          ]}
          defaultValue={discountType}
          titleSize='0.7em'
          name='discount_type'
          className='discount-radio-display'
          onChange={handleDiscountType}
        />
        {discountType === 'nominal' ? (
          <div className='nominal-wrapper'>
            <div
              className={`discount-input-display ${
                discountError && 'error-ctn'
              }`}
            >
              <span>IDR</span>
              <input
                className='discount-input-area'
                onChange={handlePercentageValue}
                value={discountValue || undefined}
                min='0'
              />
            </div>
            <div className='nominal-max-discount'>{`MAKS. ${formatMoney(
              maxDiscount,
              0,
              'IDR'
            )}`}
            </div>
          </div>
        ) : (
          <div className='discount-wrapper'>
            <div className='discount-input-display-percent'>
              <div
                className={`discount-wrapper-percent-input ${
                  discountError && 'error-ctn'
                }`}
              >
                <input
                  className='discount-input-area-error'
                  onChange={handlePercentageValue}
                  value={discountPercent || undefined}
                  min='0'
                />
                <span>%</span>
              </div>
              <div
                className={`discount-input-area-error-disabled  ${
                  discountError && 'error-ctn'
                }`}
              >
                {isNaN(discountValue)
                  ? formatMoney(0, 0, 'IDR')
                  : formatMoney(discountValue, 0, 'IDR')}
              </div>
            </div>
            <div className='nominal-max-discount'>{`MAKS. ${maxDiscountPercent}%`}</div>
          </div>
        )}
      </DiscountInputWrapper>
    )
  }

  const getAmountContainer = useCallback(
    ({ title, amount, fontWeight = '600', color = '' }) => {
      return (
        <PaymentTotalText fontWeight={fontWeight} textColor={color}>
          <div>{title}</div>
          <div>{amount}</div>
        </PaymentTotalText>
      )
    },
    []
  )

  return (
    <PaymentBreakupWrraper>
      <PaymentDetailCtn>
        <PaymentHeader>{LANG_STRINGS.totalTransactionDetail}</PaymentHeader>
        {
          getAmountContainer({
            title: LANG_STRINGS.basicPremium,
            amount: formatMoney(paymentMap.basic_premium, 0, 'IDR'),
            fontWeight: '800'
          })
        }
        <Hr />
        {
          getAmountContainer({
            title: LANG_STRINGS.subTotal,
            amount: formatMoney(paymentMap.sub_total, 0, 'IDR'),
            fontWeight: '800'
          })
        }
        {
          getAmountContainer({
            title: LANG_STRINGS.stampDuty,
            amount: formatMoney(paymentMap.stamp_duty, 0, 'IDR'),
            fontWeight: '600',
            color: '#666666'
          })
        }
        {
          getAmountContainer({
            title: LANG_STRINGS.adminFee,
            amount: formatMoney(paymentMap.admin_fee, 0, 'IDR'),
            fontWeight: '600',
            color: '#666666'
          })
        }
        <Hr />
        {
          !showDiscountAmount && (
            <>
              <DiscountWrraper>
                <DiscountHeader showAddDiscount={showAddDiscount}>
                  <CustomText
                    color={
                      showAddDiscount ? AgentColorPallette.darkRed : AgentColorPallette.skyBlue
                    }
                    size='10px'
                    weight={800}
                  >
                    {LANG_STRINGS.discount}
                  </CustomText>
                  <CustomText
                    color={
                      showAddDiscount ? AgentColorPallette.darkRed : AgentColorPallette.skyBlue
                    }
                    size='15px'
                    weight={800}
                    onClick={handleShowAddDiscount}
                  >
                    {showAddDiscount ? 'x' : '+'}
                  </CustomText>
                </DiscountHeader>
              </DiscountWrraper>
              {showAddDiscount && renderDiscountAddContainer(discountType)}
            </>
          )
        }
        {showDiscountAmount && (
          getAmountContainer({
            title: LANG_STRINGS.discount,
            amount: `- ${formatMoney(paymentMap.discount_amount, 0, 'IDR')}`,
            fontWeight: '600',
            color: '#FA3C46'
          })
        )}
      </PaymentDetailCtn>
      <TotalTransaction>
        <CustomText size='12px' weight={800}>
          {LANG_STRINGS.totalTransaction}
        </CustomText>
        <CustomText size='12px' weight={800}>
          {formatMoney(totalBill, 0, 'IDR')}
        </CustomText>
      </TotalTransaction>
    </PaymentBreakupWrraper>
  )
}
export default PaymentBreakUp
