import { useEffect, useState } from 'react'
import Accordion from './TravelAccordion.js'
import { AccordionWrapper, AccordionHeading } from './index.style.js'

const AccordionComponent = ({ data = [], title = '' }) => {
  const [accData, setAccData] = useState(data)

  useEffect(() => {
    const updatedData = title === 'Daftar Benefit' ? accData.map(( curr) => {
        return {title: Object.keys(curr)[0], data: Object.values(curr)[0]}
    }) : accData
    setAccData(updatedData)
  }, [])
  return (
      <AccordionWrapper>
        <AccordionHeading>
          {title}
        </AccordionHeading>
        {accData && accData.map((item) => {
          return (
            <>
              <Accordion title={item.title} data={item.data} parentTitle={title}/>
            </>
          )
        })}
      </AccordionWrapper>
  )
}
export default AccordionComponent
