import { RadioWithIconBoxStyle } from './index.style'
import { useCallback, useState } from 'react'
import { CustomText } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import FormItemLabel from '../FormItemLabel/index'
import { DisplayFlexRCC } from '../../../../commonStyle/index.style'

function RadioWithIconBox ({
  name, title, data = [], required, defaultValue,
  disabled, onChange = () => {}
}) {
  const [type, setType] = useState(defaultValue)

  const handleType = useCallback((item) => {
    if (disabled) return
    setType(item.value)
    onChange({
      value: item.value,
      name
    })
  }, [onChange, name, disabled])

  const renderRadioBox = useCallback(() => {
    return data.map((item) => {
      return (
        <div
          className={`transportation-box ${(type === item.value) && 'active-transport'}`}
          onClick={() => handleType(item)}
          key={item.value}
        >
          <DisplayFlexRCC>
            <img src={item.icon} alt={item.title} />
          </DisplayFlexRCC>
          <CustomText
            color={AgentColorPallette.blackGrey}
            size='0.9em'
            top='0.3rem'
            textAlign='center'
          >
            {item.title}
          </CustomText>
        </div>
      )
    })
  }, [type, data, handleType])

  return (
    <RadioWithIconBoxStyle col={data.length}>
      <FormItemLabel
        title={title}
        required={required}
      />
      <div className='radio-container'>
        {renderRadioBox()}
      </div>
    </RadioWithIconBoxStyle>
  )
}

export default RadioWithIconBox
