import { useCallback, useState } from 'react'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { OFFLINE_FORM_DATA } from '../../../../../constants/cookies'
import { setToLocalStorage } from '../../../../../helpers/localstorage'
import { mapOnlineDataToOffline } from '../../../../../helpers/mobilDataMapping'
import { ITEM_NOT_FOUND } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { PackageNotFoundStyle } from './index.style'
import Button from '../../../../../components/Button/index'
import MoreOptions from '../../../../../components/MoreOptions'
import { PKG_NOT_FOUND_ACTIONS } from '../../constants'
import ProductBottomSheet from '../../../../../components/ProductBottomSheet/index'

function PackageNotFound ({ history, productCode, showProductBtn = true, url = '' }) {
  const [showProduct, setShowProduct] = useState()
  const handleToManualPolicy = useCallback(() => {
    setToLocalStorage(OFFLINE_FORM_DATA, mapOnlineDataToOffline())
    history.push({
      pathname: url ? `/${url}` : `/${productCode}/manual-order/order`
    })
  }, [history, productCode])

  const handleMoreActions = useCallback(({ type }) => {
    if (type === 'createMoreProtection') {
      setShowProduct(true)
      return
    }
    history.replace({
      pathname: '/dashboard'
    })
  }, [history])

  return (
    <PackageNotFoundStyle>
      <img src={ITEM_NOT_FOUND} width='200' height='200' alt='Package Not Found' />
      <CustomText
        size='1.4em'
        color={AgentColorPallette.black}
        weight={700}
        bottom='10px'
        top='10px'
        textAlign='center'
      >
        {LANG_STRINGS.notFound}
      </CustomText>
      <CustomText
        size='1em'
        color={AgentColorPallette.darkCharcoal}
        bottom='10px'
        textAlign='center'
      >
        {LANG_STRINGS.thereAreNoOffersForYourCriteria}
      </CustomText>
      {showProductBtn && <Button onClick={handleToManualPolicy}>
        {LANG_STRINGS.useManualOrders}
      </Button>}
      <MoreOptions
        onActionClick={handleMoreActions}
        actions={PKG_NOT_FOUND_ACTIONS}
        gridColCount={2}
      />
      {
        showProduct && (
          <ProductBottomSheet
            show={showProduct}
            onClose={() => setShowProduct(false)}
          />
        )
      }
    </PackageNotFoundStyle>
  )
}

export default PackageNotFound
