import { useState } from "react";
import {
  AccordionItems,
  AccordionTitle,
  AccordionData,
  ArrowWrapper,
  AccDetailValue,
  AccDetailKey,
  Text,
  OrderedList,
  ChildOrderedList,
} from "./index.style";
import { GREEN_CHECK_V3, CLOSE_ICON } from "../../images";

const Accordion = ({ title, data = [], parentTitle }) => {
  const [isActive, setIsActive] = useState(true);

  const isBoolean = (val) => {
    return val === false || val === true;
  };

  const renderComponent = (acc) => {
    if (
      parentTitle === "Syarat & Ketentuan" ||
      parentTitle === "Cara Pengajuan Klaim"
    ) {
      return Object.keys(acc)?.map((currItem) => {
        if (currItem === "ol") {
          return (
            <OrderedList>
              {Object.keys(acc[currItem])?.map((list) => {
                if (list.includes("childList")) {
                  return (
                    <ChildOrderedList>
                      {Object.keys(acc[currItem][list])?.map((lists) => {
                        return <li>{acc[currItem][list][lists]}</li>;
                      })}
                    </ChildOrderedList>
                  );
                }
                return <li>{acc[currItem][list]}</li>;
              })}
            </OrderedList>
          );
        }
        return <Text>{acc[currItem]}</Text>;
      });
    } else {
      const title = Object.keys(acc)[0];
      const itemData = Object.values(acc)[0];
      return (
        <AccordionData>
          <AccDetailKey>{title}</AccDetailKey>
          <AccDetailValue>
            {isBoolean(itemData) ? (
              itemData ? (
                <img
                  src={GREEN_CHECK_V3}
                  height="7px"
                  width="9px"
                  alt="greenCheck"
                />
              ) : (
                <img
                  src={CLOSE_ICON}
                  height="7px"
                  width="9px"
                  alt="greenCheck"
                />
              )
            ) : (
              itemData
            )}
          </AccDetailValue>
        </AccordionData>
      );
    }
  };

  return (
    <AccordionItems>
      <AccordionTitle onClick={() => setIsActive(!isActive)}>
        {title}
        <ArrowWrapper>
          {isActive ? (
            <i className="fas fa-angle-up" />
          ) : (
            <i className="fas fa-angle-down" />
          )}
        </ArrowWrapper>
      </AccordionTitle>
      {isActive && data.length && data?.map((acc) => renderComponent(acc))}
    </AccordionItems>
  );
};
export default Accordion;
