import { useCallback, useRef } from 'react'
import { LANG_STRINGS } from '../../../../lang'
import DatePicker from '../DatePicker'
import moment from 'moment'
import TimePicker from '../TimePicker'
import { DateTimePickerStyle } from './index.style'

function DateTimePicker ({
  name, onChange = () => {},
  minDate = '', maxDate = '',
  minTime = '', maxTime = '',
  invalid
}) {
  const that = useRef({})

  const handleChange = useCallback((data) => {
    that.current = {
      ...that.current,
      [data.name]: data.value
    }
    if (that.current.date && that.current.time) {
      let dateTimeString = moment(that.current.date).format('YYYY-MM-DD')
      dateTimeString = `${dateTimeString}T${that.current.time}`
      onChange({
        [name]: dateTimeString
      })
    }
  }, [name, onChange])

  return (
    <DateTimePickerStyle>
      <DatePicker
        name='date'
        onChange={(data) => handleChange(data)}
        title={LANG_STRINGS.selectDate}
        minDate={moment(minDate).format('YYYY-MM-DD')}
        maxDate={moment(maxDate).format('YYYY-MM-DD')}
        invalid={invalid}
      />
      <TimePicker
        name='time'
        onChange={(data) => handleChange(data)}
        minTime={minTime}
        maxTime={maxTime}
      />
    </DateTimePickerStyle>
  )
}

export default DateTimePicker
