import { Grid, Row } from '../../commonStyle/index.style'
import { PolicyPaymentInfoStyle } from './index.style'
import CustomText from '../CustomText/index'
import { LANG_STRINGS } from '../../lang/index'
import { AgentColorPallette } from '../../configs/colorPallete'
import { formatMoney } from '../../helpers/utility'
import Button from '../Button/index'
import { useState, forwardRef, useMemo, useEffect } from 'react'
import PaymentBottomSheet from './components/PaymentBottomSheet'
import { useHistory } from 'react-router'
import { useUpdateGlobal } from '../../state/globalState/hooks/useGlobalContext'

function PolicyPaymentInfo ({
  btnText = LANG_STRINGS.buy,
  openButtonText = LANG_STRINGS.save,
  isRedirectedText = LANG_STRINGS.backToInformation,
  donotShowPaymentBtnText = LANG_STRINGS.backToInformation,
  onCloseReview = () => {},
  onShareClick = () => {},
  showDiscount,
  policy = {},
  paymentReview = false,
  onSaveDraft = () => {},
  showPaymentInfo = true,
  setShowPageLoader = false,
  isDisableButton = false,
  isRedirected = false,
  showDiscountCtn = true,
  showDiscountAmount = false
}) {
  const history = useHistory()
  const [openPayment, setOpenPayment] = useState(false)
  const [disableBtn, setDisableBtn] = useState(false)
  const [discount, setDiscount] = useState(0)
  const [{ globalState: { isLoggedIn } = { }, agentDetails = {}}] = useUpdateGlobal()
  const { lv_details } = agentDetails
  const [maxDiscount, setMaxDiscount] = useState(0)
  const paymentMap = useMemo(() => {
    return {
      basic_premium: policy.basic_premium ? policy.basic_premium : 0,
      sub_total: policy.sub_total ? policy.sub_total : 0,
      stamp_duty: policy.stamp_duty ? policy.stamp_duty : 0,
      admin_fee: policy.admin_fee ? policy.admin_fee : 0,
      discount_amount: discount,
      discount_percentage: policy.discount_percentage
    }
  }, [policy, discount])

  const getTotalBill = (subTotal = 0, stampDuty = 0, adminFee = 0, discount = 0) => {
    return subTotal + stampDuty + adminFee - discount
  }

  useEffect(() => {
    if(lv_details){
      const maxDiscountValue = (policy.basic_premium * 25) / 100;
      setMaxDiscount(maxDiscountValue)
    }
  }, [lv_details, maxDiscount])

  useEffect(() => {
    setDiscount(policy.discount)
  }, [policy.discount])

  const handleDiscount = (discount) => {
    setDiscount(discount)
  }

  const handleBuy = (discountAmount) => {
    onSaveDraft({
      discountAmount
    })
  }

  const getGridColumns = () => {
    if (!showPaymentInfo || (isRedirected && !showDiscountCtn)) return '1fr'
    return openPayment ? '1fr' : isLoggedIn ? '1fr 1fr 1fr' : '1fr 1fr'
  }

  const handleBackClick = () => {
    history.goBack()
  }

  return (
    <PolicyPaymentInfoStyle>
      <Grid
        gridColumn={getGridColumns()}
        gridGap='0.8rem'
        className='action-grid'
      >
        {
          isRedirected && (
            <Button
              className='button'
              onClick={() => handleBackClick()}
              id='mobil-detail-agent-buy-pkg-click'
              color={AgentColorPallette.blackGrey}
              disabled={disableBtn || isDisableButton}
            >
              {isRedirectedText}
            </Button>
          )
        }
        {!paymentReview && !openPayment && showPaymentInfo && showDiscountCtn && (
          <div onClick={() => setOpenPayment((oldValue) => !oldValue)}>
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size='0.7em'
              weight={700}
            >
              {LANG_STRINGS.totalBill}
            </CustomText>
            <Row>
              <CustomText
                color={AgentColorPallette.blackGrey}
                size='0.75em'
                weight={700}
              >
                {formatMoney(getTotalBill(policy.sub_total, policy.stamp_duty, policy.admin_fee, discount), 0, 'IDR')}
              </CustomText>
              <CustomText size='12px' weight={700} color={AgentColorPallette.regular} padLeft='10px'>
                <i
                  className={`fas fa-angle-up ${
                    openPayment ? 'caret-rotate-up' : 'caret-rotate-down'
                  }`}
                />
              </CustomText>
            </Row>
          </div>
        )}

       { isLoggedIn && !isRedirected &&
          <Button
            className='button'
            onClick={onShareClick}
            id='mobil-detail-agent-buy-pkg-click'
            color={AgentColorPallette.blackGrey}
            disabled={disableBtn || isDisableButton}
          >
            {LANG_STRINGS.share}
          </Button>
        }
        
        {!openPayment && showPaymentInfo && showDiscountCtn && (
          <Button
            className='button'
            onClick={() => {
              handleBuy(discount)
              setShowPageLoader(true)
            }}
            id='mobil-detail-agent-buy-pkg-click'
            color={AgentColorPallette.blackGrey}
            disabled={disableBtn || isDisableButton}
          >
            {btnText}
          </Button>
        )}
        {openPayment && showPaymentInfo && showDiscountCtn && (
          <Button
            className='button'
            id='mobil-detail-agent-buy-pkg-click'
            color={AgentColorPallette.blackGrey}
            onClick={() => {
              handleBuy(discount)
              paymentReview ? onCloseReview(false) : setOpenPayment(false)
            }}
            disabled={disableBtn || isDisableButton}
          >
            {openButtonText}
          </Button>
        )}
        {!showPaymentInfo && showDiscountCtn && (
          <Button
            className='button'
            id='mobil-detail-agent-buy-pkg-click'
            color={AgentColorPallette.blackGrey}
            onClick={handleBackClick}
          >
            {donotShowPaymentBtnText}
          </Button>
        )}
      </Grid>
      {openPayment && (
        <PaymentBottomSheet
          show={openPayment || paymentReview}
          onClose={() => {
            paymentReview ? onCloseReview(false) : setOpenPayment(false)
          }}
          policy={{
            ...policy,
            total_bill: getTotalBill(policy.sub_total, policy.stamp_duty, policy.admin_fee, discount)
          }}
          disabled={false}
          showDiscount={showDiscount}
          maxDiscountPercent={!lv_details ? policy.discount_percentage : 25}
          maxDiscount={!lv_details ? policy.max_discount : maxDiscount}
          paymentMap={paymentMap}
          onDiscountChange={handleDiscount}
          setDisableBtn={setDisableBtn}
          handleBuy={handleBuy}
          isRedirected={isRedirected}
          showDiscountCtn={showDiscountCtn}
          showDiscountAmount={showDiscountAmount}
        />
      )}
    </PolicyPaymentInfoStyle>
  )
}

export default forwardRef(PolicyPaymentInfo)
