import { useEffect, useState, useCallback } from 'react'
import Container from '../../../../../../../components/Container'
import PackageDetailCard from '../PackageList/packageDetailCard'
import {
  PackageDetailCtn,
  ContactUsctn,
  ImageCtn,
  ContactUsDetail,
  CustomerService,
  HelplineDetail,
  ContactUsHeading,
  TabCtn
} from './index.style'
import PolicyPaymentInfo from '../../../../../../../components/TravelPaymentInfo'
import AccordionComponent from '../../../../../../../components/TravelPriceAccordion'

import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang'
import Tabs from '../../../../../../../components/Tabs'
import {
  useGetCustomerTravelDetails,
  useGetPackageDetail,
  useGetTravelDetails,
  useUpdateTravelDraft
} from '../../../../state/hooks/useTravelState'
import { TRAVEL_STEPS, tncData } from '../../../../constant'
import { useHistory, useParams } from 'react-router'
import { get } from 'lodash'
import PolicyStepsHeader from '../../../../../../../components/PolicyStepsHeader'
import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
  useResetError
} from '@pasarpolis/common-react-hooks'
import PackageNotFound from '../../../../../Packages/components/PackageNotFound'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import ShareQuotation from '../../../ShareQuotationTravel'
import { useUpdateGlobal } from '../../../../../../../state/globalState/hooks/useGlobalContext'

const TABS = [
  {
    title: LANG_STRINGS.benefit,
    value: 'options'
  },
  {
    title: LANG_STRINGS.claim,
    value: 'benefit'
  },
  {
    title: LANG_STRINGS.SNK,
    value: 'terms'
  }
]

const PackageDetail = (props) => {
  const { id } = useParams()
  const history = useHistory()
  const { resetError } = useResetError()
  const [{ globalState: { isLoggedIn } = { } }] = useUpdateGlobal()
  const [paymentReview, setPaymentReview] = useState(false)
  const [, updateTravelDraftRequest] = useUpdateTravelDraft()
  const [{ updateTravelDraftStatus }] = useErrorContextValue()
  const [showPageLoader, setShowPageLoader] = useState(false)
  const [
    { getPackagesDetailData = {} },
    getPackagesRequest
  ] = useGetPackageDetail()
  const [
    { getTravelDetailsData = {} },
    getTravelDetailsRequest
  ] = useGetTravelDetails()
  const [{ getCustomerDraftQuoteDetailData = {} }, getCustomerDraftQuoteDetailRequest] = useGetCustomerTravelDetails()
  const [
    { GET_PACKAGES_DETAIL_LOADER, UPDATE_TRAVEL_DRAFT_LOADER },
    dispatchLoader
  ] = useLoaderContextValue()
  const { state: { activeTab: currActiveTab = 0, isRedirected = false, showDiscountCtn = true } = {} } = props.location || {}
  const activeTabData = {
    Manfaat: getPackagesDetailData?.benefit_list || [],
    Klaim: tncData.klaim || [],
    Detil: tncData.detil || []
  }
  const [activeTab, setActiveTab] = useState(TABS[currActiveTab])
  const [showShareSheet, setShowShareSheet] = useState(false)

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_PACKAGES_LOADER: undefined
        })
      )
    }
  }, [dispatchLoader])

  const getInitialPackages = useCallback(() => {
    if (isLoggedIn && Object.keys(getTravelDetailsData).length) {
      const payload = {
        purchase_type: 'new-purchase',
        code: 'travel-protection',
        start_date: get(getTravelDetailsData.policy_details, 'start_date'),
        end_date: get(getTravelDetailsData.policy_details, 'end_date'),
        travel_type: get(getTravelDetailsData.policy_details, 'travel_type'),
        source: get(getTravelDetailsData.policy_details, 'source'),
        destination: get(getTravelDetailsData.policy_details, 'destination'),
        destination_data: get(getTravelDetailsData.policy_details, 'destination_data'),
        policy_type: get(getTravelDetailsData.policy_details, 'policy_type'),
        schengen_visa: get(getTravelDetailsData.policy_details, 'schengen_visa'),
        additional_member_count: get(
          getTravelDetailsData.policy_details,
          'additional_member_count'),
        package_code: get(getTravelDetailsData.policy_details, 'package_code')
      }
      getPackagesRequest({
        body: {
          ...payload
        }
      })
    }
  }, [getPackagesRequest, isLoggedIn, getTravelDetailsData])

  const getInitialPackagesCutomer = useCallback(() => {
    if (!isLoggedIn && Object.keys(getCustomerDraftQuoteDetailData).length) {
      const payload = {
        purchase_type: 'new-purchase',
        code: 'travel-protection',
        start_date: get(getCustomerDraftQuoteDetailData.policy_details, 'start_date'),
        end_date: get(getCustomerDraftQuoteDetailData.policy_details, 'end_date'),
        travel_type: get(getCustomerDraftQuoteDetailData.policy_details, 'travel_type'),
        source: get(getCustomerDraftQuoteDetailData.policy_details, 'source'),
        destination: get(getCustomerDraftQuoteDetailData.policy_details, 'destination'),
        destination_data: get(getCustomerDraftQuoteDetailData.policy_details, 'destination_data'),
        policy_type: get(getCustomerDraftQuoteDetailData.policy_details, 'policy_type'),
        schengen_visa: get(getCustomerDraftQuoteDetailData.policy_details, 'schengen_visa'),
        additional_member_count: get(getCustomerDraftQuoteDetailData.policy_details,
          'additional_member_count'
        ),
        package_code: get(getCustomerDraftQuoteDetailData.policy_details, 'package_code')
      }
      getPackagesRequest({
        body: {
          ...payload
        }
      })
    }
  }, [getPackagesRequest, isLoggedIn, getCustomerDraftQuoteDetailData])

  useEffect(() => {
    if (isLoggedIn) {
      getInitialPackages()
    }
  }, [getInitialPackages, isLoggedIn])

  useEffect(() => {
    if (!isLoggedIn) {
      getInitialPackagesCutomer()
    }
  }, [getInitialPackagesCutomer, isLoggedIn])

  useEffect(() => {
    if (isLoggedIn && id) {
      getTravelDetailsRequest({ draftQuoteId: id })
    }
  }, [getTravelDetailsRequest, id, isLoggedIn])

  useEffect(() => {
    if (!isLoggedIn && id) {
      getCustomerDraftQuoteDetailRequest({ draftQuoteId: id })
    }
  }, [getCustomerDraftQuoteDetailRequest, id, isLoggedIn])

  const handleTabClick = (tab) => {
    setActiveTab(tab)
  }

  useEffect(() => {
    if (updateTravelDraftStatus === 'success' && showPageLoader) {
      history.push({
        pathname: `/travel/registration/${id}`
      })
    }
  }, [updateTravelDraftStatus, showPageLoader])

  const handleSaveDraft = ({ discountAmount = 0 }) => {
    if (isLoggedIn) {
      updateTravelDraftRequest({
        body: {
          section: 'package_insurance',
          sub_section: 'package_details',
          data: {
            ...getTravelDetailsData.policy_details,
            discount: discountAmount,
            code: getTravelDetailsData.policy_details.package_code,
            provider_package_code: getTravelDetailsData.policy_details.package_code,
            package_data: {
              ...getPackagesDetailData
            }
          }
        },
        draftQuoteId: id
      })
    }
  }

  const handleShowQuotationModal = ({ discountAmount = 0 }) => {
    setShowShareSheet(true)
    updateTravelDraftRequest({
      body: {
        section: 'package_insurance',
        sub_section: 'package_details',
        data: {
          ...getTravelDetailsData.policy_details,
          discount: discountAmount,
          code: getTravelDetailsData.policy_details.package_code,
          provider_package_code: getTravelDetailsData.policy_details.package_code,
          package_data: {
            ...getPackagesDetailData
          }
        }
      },
      draftQuoteId: id
    })
  }

  const handleBackClick = () => {
    history.push({
      pathname: `/travel/insured_package/${id}`
    })
  }

  useEffect(() => {
    if (updateTravelDraftStatus !== 'success' && updateTravelDraftStatus !== undefined) {
      ShowSnackbar.error({
        visible: true,
        text: `${ERROR_LANG.errorWhileUpdating}`
      })
    }
    resetError(['updateTravelDraftStatus'])
  }, [updateTravelDraftStatus, resetError])

  return (
    <Container
      title='Detail Paket'
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      showInnerHeader
      displayBackButton
      hideBottomTabs
      loader={GET_PACKAGES_DETAIL_LOADER || UPDATE_TRAVEL_DRAFT_LOADER}
      onBackClick={handleBackClick}
    >
      {!isRedirected && <PolicyStepsHeader
        stepsData={TRAVEL_STEPS}
        activeCount={2}
        prevActive={{
          1: true
        }}
      />}
      {getPackagesDetailData.code && (
        <PackageDetailCtn>
          <PackageDetailCard props={getPackagesDetailData} />
        </PackageDetailCtn>
      )}
      {getPackagesDetailData.code && (
        <TabCtn>
          <Tabs
            data={TABS}
            defaultTab={activeTab}
            top='90px'
            borderBottom='#333333'
            onClick={handleTabClick}
            isSticky
          />
          {activeTab.title === 'Manfaat' && activeTabData.Manfaat && (
            <AccordionComponent
              data={activeTabData.Manfaat}
              title='Daftar Benefit'
            />
          )}
          {activeTab.title === 'Klaim' && activeTabData.Klaim && (
            <>
              <AccordionComponent
                data={activeTabData.Klaim}
                title='Cara Pengajuan Klaim'
              />
            </>
          )}
          {activeTab.title === 'S&K' && activeTabData.Detil && (
            <>
              <ContactUsctn>
                <ContactUsHeading>Detail Asuransi</ContactUsHeading>
                <ContactUsDetail>
                  <ImageCtn>
                    <img
                      src={getPackagesDetailData?.provider?.logo_url}
                      width={48}
                      height={48}
                      alt='logo'
                      className='logo-image'
                    />
                  </ImageCtn>
                  <CustomerService>
                    {LANG_STRINGS.tapTravel}
                  </CustomerService>
                  <HelplineDetail>
                    {LANG_STRINGS.premiumTravelInsuranceDetails}
                  </HelplineDetail>
                </ContactUsDetail>
              </ContactUsctn>
              <AccordionComponent
                data={activeTabData.Detil}
                title='Syarat & Ketentuan'
              />
            </>
          )}
        </TabCtn>
      )}
      {getPackagesDetailData.code && (
        <PolicyPaymentInfo
          policy={{
            basic_premium: getPackagesDetailData.basic_premium,
            sub_total: getPackagesDetailData.basic_premium,
            admin_fee: getPackagesDetailData.admin_fee,
            stamp_duty: getPackagesDetailData.stamp_duty,
            total_bill:
              getPackagesDetailData.sub_total ||
              getPackagesDetailData.total_bill,
            discount: getTravelDetailsData.policy_details?.discount,
            discount_percentage: getPackagesDetailData.discount_percentage,
            max_discount: getPackagesDetailData.max_discount
          }}
          onShareClick={handleShowQuotationModal}
          onBuyClick={() => setPaymentReview(true)}
          paymentReview={paymentReview}
          onCloseReview={() => setPaymentReview(false)}
          showDiscount
          onSaveDraft={handleSaveDraft}
          setShowPageLoader={setShowPageLoader}
          isRedirected={isRedirected}
          showDiscountCtn={showDiscountCtn}
        />
      )}
      {
        (GET_PACKAGES_DETAIL_LOADER === false) && !getPackagesDetailData.code && (
          <PackageNotFound history={history} showProductBtn={false} />
        )
      }
      {
        showShareSheet && (
          <ShareQuotation
            show={showShareSheet}
            onClose={() => setShowShareSheet(false)}
          />
        )
      }
    </Container>
  )
}

export default PackageDetail
