import { createPortal } from 'react-dom'
import { Button, CustomText } from '../../../components'
import BottomActionSheet from '../../../components/BottomActionSheet'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { MV_RENEWAL_STATUS } from '../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../lang/index'
import { formatDate } from '../../../helpers/formatDate'
import {
  ContentContainer,
  VehicleLogoContainer,
  VehicleDetailsContainer,
  VehicleDetailsStatus,
  VehicleDetailsGrid,
  VehicleDetailsExpiryReminder,
} from '../container/index.style'

const VEHICLE_SUMMARY = [
  {
    title: 'Pemegang Polis',
    render: (data) => data?.customer_data?.name,
  },
  {
    title: 'Nomor Plat',
    render: (data) =>
      [data?.region_code, data?.plate_number, data?.back_plate].join(' '),
  },
  {
    title: 'Periode Polis',
    render: (data) =>
      [
        formatDate(data?.coverage_period_start),
        formatDate(data?.coverage_period_end),
      ].join(' - '),
  },
  {
    title: 'Tahun Kendaraan',
    render: (data) => data?.year,
  },
]

function FoundVehicleDetails({
  show,
  vehicleData,
  onClose,
  onClickBack,
  onClickBegin,
  onClickEndorsement,
}) {
  const isPolicyExpired = vehicleData?.is_expired
  const isRenewable =
    vehicleData?.renewal_status === MV_RENEWAL_STATUS.RENEWAL ||
    vehicleData?.renewal_status === MV_RENEWAL_STATUS.REACTIVATION
  const isEndorsable =
    vehicleData?.renewal_status === MV_RENEWAL_STATUS.EXTENSION &&
    vehicleData?.is_same_agent

  return createPortal(
    <BottomActionSheet
      onCloseSheet={onClose}
      show={show}
      zIndex={5}
      showHeader
      backGroundColor={AgentColorPallette.white}
    >
      <ContentContainer>
        <VehicleDetailsContainer>
          <VehicleLogoContainer>
            <img src={vehicleData?.brand_data?.logo} alt="" />
          </VehicleLogoContainer>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size="0.8em"
            weight={700}
            textAlign="center"
            marginBottom="8px"
          >
            {vehicleData?.brand_data?.name}
          </CustomText>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size="0.9em"
            weight={800}
            textAlign="center"
          >
            {vehicleData?.model_data?.model_name}
          </CustomText>

          <VehicleDetailsStatus isPolicyExpired={isPolicyExpired}>
            {isPolicyExpired
              ? LANG_STRINGS.policyStatusExpired
              : LANG_STRINGS.policyStatusActive}
          </VehicleDetailsStatus>

          {isRenewable && !isPolicyExpired && (
            <VehicleDetailsExpiryReminder>
              {LANG_STRINGS.renewalsExpiryReminder(
                `${formatDate(vehicleData?.coverage_period_end, 'DD/MM/YYYY')}, 11:59:59` // Hardcode date to EOD
              )}
            </VehicleDetailsExpiryReminder>
          )}

          <VehicleDetailsGrid>
            {VEHICLE_SUMMARY.map((item, index) => (
              <div key={item.title} className="content-row">
                <CustomText
                  color={AgentColorPallette.fontGrey}
                  size="0.6em"
                  weight={600}
                  textAlign={index % 2 === 0 ? 'left' : 'right'}
                >
                  {item.title}
                </CustomText>
                <CustomText
                  color={AgentColorPallette.darkCharcoal}
                  size="0.8em"
                  weight={700}
                  textAlign={index % 2 === 0 ? 'left' : 'right'}
                >
                  {item.render(vehicleData)}
                </CustomText>
              </div>
            ))}
          </VehicleDetailsGrid>
        </VehicleDetailsContainer>

        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size="0.8em"
          weight={600}
          top="16px"
          bottom="16px"
          textAlign="center"
        >
          {isRenewable || isEndorsable
            ? LANG_STRINGS.renewalsPleaseReviewVehicleData
            : LANG_STRINGS.renewalsCannotRenew}
        </CustomText>

        {isRenewable && (
          <Button
            variant="filled"
            handleClick={onClickBegin}
            style={{ marginBottom: 8 }}
          >
            {LANG_STRINGS.renewalPolicy}
          </Button>
        )}
        {isEndorsable && (
          <Button
            variant="filled"
            handleClick={onClickEndorsement}
            style={{ marginBottom: 8 }}
          >
            {LANG_STRINGS.endorsement}
          </Button>
        )}
        <Button variant="outlined" handleClick={onClickBack}>
          {LANG_STRINGS.return}
        </Button>
      </ContentContainer>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default FoundVehicleDetails
