import { ERROR_LANG, LANG_STRINGS } from '../../../lang'

export const getAddressForm = (addressData = {}) => {
  const { defaultValue, designV2 } = addressData
  return [
    {
      type: designV2 ? 'autoSearchBottomSheetv2' : 'autoSearchBottomSheet',
      placeholder: LANG_STRINGS.selectProvince,
      name: 'province_code',
      title: LANG_STRINGS.selectProvince,
      data: {
        data: addressData?.getProvinceListData,
        dataKey: 'province_code',
        displayKey: 'province_name'
      },
      defaultValue: (defaultValue.province_code) && {
        province_code: defaultValue?.province_code?.province_code,
        province_name: defaultValue?.province_code?.province_name
      },
      required: true
    },
    {
      type: designV2 ? 'autoSearchBottomSheetv2' : 'autoSearchBottomSheet',
      placeholder: LANG_STRINGS.selectCity,
      name: 'city_code',
      title: LANG_STRINGS.selectCity,
      data: {
        data: addressData?.getCityListData,
        dataKey: 'city_code',
        displayKey: 'city_name'
      },
      defaultValue: (defaultValue.city_code) && {
        city_code: defaultValue?.city_code?.city_code,
        city_name: defaultValue?.city_code?.city_name,
        region: defaultValue?.city_code?.region
      },
      required: true
    },
    {
      type: designV2 ? 'inputV2' : 'postal_code',
      validationType: designV2 ? 'postal_code' : undefined,
      title: LANG_STRINGS.postalCode,
      placeholder: LANG_STRINGS.postalCode,
      defaultValue: defaultValue?.postal_code,
      name: 'postal_code',
      maxLength: 5,
      required: true,
      error: ERROR_LANG.postalCodeError
    },
    {
      type: designV2 ? 'inputV2' : 'textarea',
      title: LANG_STRINGS.address,
      placeholder: '',
      defaultValue: defaultValue?.address,
      name: 'address',
      minLength: 10,
      maxLength: 100,
      required: true,
      error: ERROR_LANG.addressBetween10and100char
    }
  ]
}
