import { useCallback, useEffect } from 'react'
import { useHistory } from 'react-router'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useGetRenewalOneTapDetails } from '../../../state/hooks/usePolicyState'

const RENEWAL_ALLOCATION = {
  AUTO_RENEW: 'AUTO_RENEW',
  TLO_ONLY: 'TLO_ONLY',
  UW_REVIEW: 'UW_REVIEW',
  DECLINE: 'DECLINE',
  NULL: null,
}

function useRenewalAllocation() {
  const history = useHistory()

  const [{ getRenewalOneTapDetailsData }, _getRenewalOneTapDetailsRequest] =
    useGetRenewalOneTapDetails()
  const [{ GET_RENEWAL_ONE_TAP_DETAILS_LOADER }] = useLoaderContextValue()

  const getRenewalOneTapDetailsRequest = useCallback(
    (policyId) => {
      if (!policyId) return
      _getRenewalOneTapDetailsRequest({ policyId })
    },
    [_getRenewalOneTapDetailsRequest]
  )

  useEffect(() => {
    getRenewalOneTapDetailsRequest()
  }, [getRenewalOneTapDetailsRequest])

  useEffect(() => {
    const draftId = getRenewalOneTapDetailsData?.data?.draft_id
    if (draftId) {
      history.push(`/motor_vehicle/v2/${draftId}`)
    }
  }, [history, getRenewalOneTapDetailsData])

  const redirectToRenewalAllocation = useCallback(
    ({ referenceId, allocation }) => {
      if (!referenceId) return null

      switch (allocation) {
        case RENEWAL_ALLOCATION.AUTO_RENEW:
        case RENEWAL_ALLOCATION.TLO_ONLY:
        case RENEWAL_ALLOCATION.UW_REVIEW:
          history.push(`/renewal/one-tap/${referenceId}`)
          return
        case RENEWAL_ALLOCATION.DECLINE:
        case RENEWAL_ALLOCATION.NULL:
        default:
          getRenewalOneTapDetailsRequest(referenceId)
          return
      }
    },
    [history, getRenewalOneTapDetailsRequest]
  )

  return {
    redirectToRenewalAllocation,
    isLoading: GET_RENEWAL_ONE_TAP_DETAILS_LOADER,
  }
}

export default useRenewalAllocation
